window.BioChecks[30] = {"2004-Q6":[{"q":"Which best describes peristalsis?","right":"Muscle contractions that push food along the gut","wrong":["Enzymes breaking food into small molecules","Villi taking digested food into the blood","Teeth grinding food into smaller pieces"],"why":"Peristalsis is waves of muscle contraction in the gut wall that squeeze food along."},{"q":"Why is a low pH useful in the stomach?","right":"It kills germs swallowed with food","wrong":["It emulsifies fats into small droplets","It helps salivary amylase work faster","It speeds up absorption of glucose"],"why":"Stomach acid kills most bacteria in food and suits pepsin; it actually stops salivary amylase working."},{"q":"Why is fibre important in the diet?","right":"It adds bulk so peristalsis moves food along","wrong":["It is digested to glucose for energy","It provides amino acids for growth","It is stored in the liver as glycogen"],"why":"We can't digest fibre; it adds bulk for the gut muscles to push on, which keeps food moving and stops constipation."},{"q":"Which enzyme digests fat?","right":"Lipase","wrong":["Amylase","Pepsin","Bile"],"why":"Lipase breaks down fats (lipids); bile only emulsifies fat and is not an enzyme."},{"q":"What are the products of fat digestion?","right":"Fatty acids and glycerol","wrong":["Amino acids and peptides","Maltose and glucose","Small droplets of fat"],"why":"Lipase splits fat into fatty acids and glycerol; small droplets come from bile, which doesn't digest anything."},{"q":"What does bile do in fat digestion?","right":"Breaks fat into small droplets (emulsifies)","wrong":["Digests fat into fatty acids and glycerol","Lowers the pH in the duodenum","Carries fat into the lacteals"],"why":"Bile emulsifies fat into tiny droplets, giving lipase more surface to work on; it is not an enzyme itself."},{"q":"What useful job do gut bacteria do?","right":"Make vitamins such as vitamin K","wrong":["Make bile to emulsify fats","Make insulin to control blood sugar","Produce hydrochloric acid"],"why":"Gut bacteria make vitamins (like K and some B) that we absorb; bile, insulin and acid come from our own organs."}],"2005-Q6":[{"q":"On the diagram, what is the central vessel B?","right":"Lacteal","wrong":["Blood capillary","Villus","Arteriole"],"why":"B is the lacteal, the lymph vessel in the middle of the villus; the capillaries form a network around it."},{"q":"Which feature helps villus A absorb soluble food?","right":"Microvilli giving a large surface area","wrong":["Cilia that sweep the food along","A thick wall several cells deep","Glands that make bile"],"why":"Villi and their microvilli give a huge surface area; the wall is only one cell thick, not thick."},{"q":"By which process are soluble foods absorbed into the blood?","right":"Diffusion","wrong":["Osmosis","Peristalsis","Emulsification"],"why":"Digested food diffuses from the gut into the blood; osmosis is only the movement of water."},{"q":"What type of food is mainly absorbed into lacteal B?","right":"Fats","wrong":["Glucose","Amino acids","Water"],"why":"Products of fat digestion go into the lacteal; glucose and amino acids go into the blood capillaries."}],"2006-Q1f":[{"q":"What are the final products of protein digestion?","right":"Amino acids","wrong":["Fatty acids","Maltose","Glycerol"],"why":"Proteases break proteins down into amino acids; fatty acids and glycerol come from fats."}],"2006-Q3":[{"q":"Which enzyme digests carbohydrate in the gut?","right":"Amylase","wrong":["Pepsin","Lipase","Trypsin"],"why":"Amylase digests starch, a carbohydrate; pepsin and trypsin digest protein and lipase digests fat."},{"q":"Where in the gut does amylase act?","right":"Mouth","wrong":["Stomach","Large intestine","Liver"],"why":"Amylase works in the mouth (from saliva) and in the small intestine (from the pancreas); stomach acid stops it."},{"q":"If the enzyme is amylase, what is its product?","right":"Maltose","wrong":["Starch","Glycogen","Amino acids"],"why":"Amylase breaks starch (its substrate) down into maltose, a double sugar."},{"q":"For this carbohydrate enzyme, what is the pH at peak A?","right":"pH 7 to 9","wrong":["pH 1 to 2","pH 4 to 5","pH 11 to 12"],"why":"Carbohydrate enzymes like amylase work best in the near-neutral to slightly alkaline mouth and small intestine."},{"q":"What word describes the pH at A?","right":"Optimum","wrong":["Neutral","Maximum","Critical"],"why":"The optimum pH is the pH at which an enzyme works fastest: the top of the curve."}],"2006-Q5":[{"q":"On the diagram, what is vessel Y?","right":"Hepatic portal vein","wrong":["Hepatic vein","Hepatic artery","Inferior vena cava"],"why":"Y carries blood from the intestine to the liver: that's the hepatic portal vein."},{"q":"Which way does blood flow in vessel Y?","right":"From the intestine to the liver","wrong":["From the liver to the intestine","From the heart to the liver","From the intestine to the heart"],"why":"The portal vein brings blood rich in digested food from the intestine into the liver."},{"q":"Where exactly is the liver in the body?","right":"Upper abdomen, just below the diaphragm","wrong":["In the chest, just above the diaphragm","Lower abdomen, below the intestine","Lower left abdomen, below the stomach"],"why":"The liver sits at the top of the abdomen, right under the diaphragm and mostly on the right side."},{"q":"What does the liver do in digestion?","right":"Makes bile","wrong":["Stores bile","Makes lipase","Absorbs digested food"],"why":"The liver makes bile; the gall bladder only stores it, and lipase comes from the pancreas."}],"2008-Q12a":[{"q":"Distinguish between mechanical and chemical digestion. (2 points)","right":"Mechanical: physically broken up; chemical: broken down by enzymes","wrong":["Mechanical: broken down by enzymes; chemical: physically broken up","Mechanical: physically broken up; chemical: absorbed into blood","Mechanical: food is egested; chemical: broken down by enzymes"],"why":"Two points: mechanical digestion breaks food up physically (chewing, churning); chemical digestion breaks molecules down with enzymes."},{"q":"Apart from teeth, which structure digests food mechanically?","right":"Stomach","wrong":["Salivary glands","Pancreas","Appendix"],"why":"The stomach's muscular wall churns food, breaking it up physically; glands like the pancreas digest chemically."}],"2008-Q12b":[{"q":"On the diagram, which part is E?","right":"Appendix","wrong":["Caecum","Rectum","Gall bladder"],"why":"E is the appendix: the small dead-end tube hanging off the start of the large intestine."},{"q":"Describe two functions of bile in digestion. (2 points)","right":"Emulsifies fats into droplets; neutralises stomach acid","wrong":["Digests fats into fatty acids; neutralises stomach acid","Emulsifies fats into droplets; makes the duodenum acidic","Breaks proteins into amino acids; emulsifies fats"],"why":"Two points: bile salts emulsify fats into small droplets, and bile is alkaline, so it neutralises acid chyme from the stomach."},{"q":"Where is lipase secreted?","right":"Pancreas","wrong":["Liver","Gall bladder","Large intestine"],"why":"Lipase is made by the pancreas; the liver makes bile, which helps but isn't an enzyme."},{"q":"Where does pancreatic lipase act?","right":"Duodenum","wrong":["Liver","Large intestine","Gall bladder"],"why":"Pancreatic lipase is released into the duodenum and digests fat there, helped by bile."},{"q":"What is the rough pH where lipase acts?","right":"pH 7 to 9","wrong":["pH 1 to 3","pH 4 to 5","pH 11 to 13"],"why":"In the duodenum, bile and pancreatic juice make the contents slightly alkaline, about pH 8."}],"2008-Q12c":[{"q":"What are symbiotic bacteria?","right":"Live inside another organism, both benefiting","wrong":["Live inside another organism, causing disease","Feed on dead and decaying organic matter","Make their own food using light energy"],"why":"Symbiotic bacteria live closely with a host to their benefit; ones that cause disease are parasites."},{"q":"Give two activities of symbiotic bacteria in the human digestive system. (2 points)","right":"Make vitamins B and K; help digest food","wrong":["Make hydrochloric acid; help digest food","Make insulin and glucagon; make vitamins","Absorb amino acids into the blood; make vitamins"],"why":"Two points: gut bacteria make vitamins (B and K) and help digest food; outcompeting harmful microbes also counts."},{"q":"Where are the products of digestion absorbed into the blood?","right":"Ileum","wrong":["Stomach","Colon","Rectum"],"why":"Most digested food is absorbed through the villi of the ileum, part of the small intestine."},{"q":"Which part of the gut absorbs water into the blood?","right":"Colon","wrong":["Oesophagus","Pancreas","Liver"],"why":"Water is absorbed from the stomach onwards, with the colon finishing the job; the oesophagus just carries food."},{"q":"Which process moves digested food into the blood?","right":"Diffusion","wrong":["Osmosis","Peristalsis","Egestion"],"why":"Small soluble food molecules diffuse into the blood; osmosis only describes water moving."},{"q":"How is the ileum adapted to absorb digested food?","right":"Villi give it a very large surface area","wrong":["Short, so food passes through fast","A thick lining many cells deep","A smooth, flat inner surface"],"why":"Folds, villi and microvilli give a huge surface area, and the lining is one cell thick, so absorption is fast."}],"2009-Q13b":[{"q":"Which is a real effect of diet on the circulatory system?","right":"Too much saturated fat clogs arteries","wrong":["Too much salt lowers blood pressure","Too much cholesterol widens arteries","Eating fibre raises blood cholesterol"],"why":"Saturated fat and cholesterol build up as fatty deposits in arteries, narrowing them and raising blood pressure."}],"2010-Q15b":[{"q":"In your diagram, the portal vein carries blood from where to where?","right":"From the small intestine to the liver","wrong":["From the liver to the heart","From the aorta to the liver","From the liver to the small intestine"],"why":"The hepatic portal vein links capillaries in the small intestine to the liver, carrying absorbed food there."},{"q":"What does the hepatic portal vein carry to the liver?","right":"Glucose","wrong":["Glycogen","Fibre","Starch"],"why":"Absorbed products of digestion like glucose and amino acids travel to the liver in the portal vein."},{"q":"Which vessel brings oxygen-rich blood to the liver?","right":"Hepatic artery","wrong":["Hepatic portal vein","Hepatic vein","Pulmonary vein"],"why":"The hepatic artery, a branch of the aorta, brings oxygen-rich blood; the portal vein brings food-rich blood."},{"q":"Where is the liver compared with the stomach?","right":"Above it and to the right","wrong":["Below it and to the left","Directly below it","Below it and to the right"],"why":"The liver sits just under the diaphragm, above and to the right of the stomach."},{"q":"Where is bile stored after the liver makes it?","right":"Gall bladder","wrong":["Liver","Pancreas","Duodenum"],"why":"Bile is made in the liver but stored in the gall bladder until fatty food reaches the duodenum."},{"q":"What do bile salts do in digestion?","right":"Break fat into small droplets","wrong":["Break fat into fatty acids and glycerol","Make the duodenum more acidic","Turn starch into maltose"],"why":"Bile salts emulsify fat into tiny droplets for lipase; it's lipase that makes fatty acids and glycerol."},{"q":"Give two functions of the liver, other than making bile. (2 points)","right":"Detoxifies poisons; deaminates spare amino acids","wrong":["Makes insulin; detoxifies poisons","Stores bile; deaminates spare amino acids","Filters urea into urine; detoxifies poisons"],"why":"Two points, e.g. detoxification and deamination; storing vitamins or glycogen, making heat and making plasma proteins also count."}],"2010-Q15c":[{"q":"Why does wholegrain cereal help with constipation? (2 points)","right":"Its fibre adds bulk and speeds up peristalsis","wrong":["It is quickly digested to glucose","It dries out the faeces","It slows food down so more is absorbed"],"why":"Wholegrains are rich in fibre, which holds water and adds bulk, so peristalsis moves faeces along faster."}],"2011-Q5":[{"q":"What does digestion mean?","right":"Breaking food down into small molecules","wrong":["Taking food into the body via the mouth","Getting rid of undigested waste food","Moving digested food into the blood"],"why":"Digestion is breaking food down; taking it in is ingestion, and getting rid of waste is egestion."},{"q":"Why is digestion needed?","right":"So food is soluble and can be absorbed","wrong":["To turn small molecules into big ones","To make food insoluble for storage","To remove poisons before absorption"],"why":"Big food molecules can't pass into the blood; digestion makes them small and soluble so they can be absorbed."},{"q":"Distinguish between mechanical and chemical digestion, with a sentence on each. (2 points)","right":"Mechanical: chewing breaks food up; chemical: enzymes digest it","wrong":["Mechanical: enzymes digest food; chemical: chewing breaks it up","Mechanical: chewing breaks food up; chemical: bile digests it","Mechanical: villi absorb food; chemical: enzymes digest it"],"why":"Two points: mechanical digestion breaks food up physically (chewing, churning); chemical digestion uses enzymes or acid."},{"q":"On the diagram, what is the C-shaped tube W?","right":"Duodenum","wrong":["Stomach","Gall bladder","Colon"],"why":"W is the duodenum, the C-shaped first part of the small intestine where bile and pancreatic juice enter."},{"q":"On the diagram, what is organ X on the bile duct?","right":"Gall bladder","wrong":["Pancreas","Stomach","Spleen"],"why":"The bile duct comes from the gall bladder, which stores bile made by the liver."},{"q":"Where does food come from as it enters W?","right":"Stomach","wrong":["Oesophagus","Ileum","Gall bladder"],"why":"Chyme leaves the stomach through the pyloric sphincter straight into the duodenum."},{"q":"What does the pancreas do in digestion?","right":"Makes enzymes such as lipase","wrong":["Makes bile to emulsify fat","Makes acid to kill bacteria","Stores glycogen for energy"],"why":"The pancreas makes pancreatic juice with enzymes like lipase, amylase and trypsin; bile comes from the liver."}],"2012-Q15a":[{"q":"Name structures X and Y on the diagram. (2 points)","right":"X: villus; Y: lacteal","wrong":["X: microvillus; Y: lacteal","X: villus; Y: capillary","X: lacteal; Y: villus"],"why":"Two points: X is a villus, a finger-like fold of the gut lining, and Y is the lacteal, the lymph vessel at its centre."},{"q":"What process do the muscle layers Z cause when they contract?","right":"Peristalsis","wrong":["Emulsification","Absorption","Egestion"],"why":"The circular and longitudinal muscles contract in waves (peristalsis), pushing food along the intestine."},{"q":"What is the pH of the small intestine contents like?","right":"Alkaline, about pH 8","wrong":["Acidic, about pH 2","Acidic, about pH 5","Neutral, exactly pH 7"],"why":"Bile and pancreatic juice contain hydrogencarbonate, which makes the small intestine slightly alkaline."},{"q":"Name two glands that pass their secretions into the small intestine. (2 points)","right":"Pancreas and liver","wrong":["Pancreas and salivary glands","Liver and gastric glands","Liver and thyroid gland"],"why":"Two points: the pancreas (pancreatic juice) and the liver (bile) both empty into the duodenum; salivary glands empty into the mouth."},{"q":"What are symbiotic bacteria?","right":"Bacteria living in a host, to their benefit","wrong":["Bacteria living in a host, causing disease","Bacteria feeding on dead organic matter","Bacteria making food by photosynthesis"],"why":"Symbiosis means living closely with another organism where at least one benefits; disease-causers are parasites."},{"q":"Give two functions of symbiotic bacteria in the alimentary canal. (2 points)","right":"Make vitamins B and K; help digest food","wrong":["Make bile to emulsify fats; help digest food","Make vitamins B and K; make insulin","Make hydrochloric acid; absorb glucose"],"why":"Two points: gut bacteria make vitamins (B and K) and help digest food such as some fibre; bile, insulin and acid are made by us."},{"q":"What answer does this marking scheme want for where most water is absorbed?","right":"Colon (large intestine)","wrong":["Stomach","Oesophagus","Mouth"],"why":"The scheme gives colon or large intestine. (In fact the small intestine absorbs more, but write colon here.)"}],"2012-Q15c":[{"q":"How does the liver help with homeostasis?","right":"Stores or releases glucose to steady blood sugar","wrong":["Filters urea out of the blood","Makes insulin to lower blood sugar","Removes carbon dioxide from the blood"],"why":"The liver takes in glucose (storing it as glycogen) or releases it; insulin comes from the pancreas."}],"2013-Q10a":[{"q":"Why is the pancreas called a dual-function gland?","right":"Makes both hormones and digestive enzymes","wrong":["Makes both bile and digestive enzymes","Makes two hormones: insulin and glucagon","Digests both fats and proteins"],"why":"It is endocrine (insulin into the blood) and exocrine (enzymes down a duct to the gut), so it has two jobs."}],"2014-Q2a":[{"q":"In the reaction, what is product Y?","right":"Glycerol","wrong":["Glucose","Glycogen","Amino acids"],"why":"Lipase (X) splits a fat into fatty acids and glycerol; glucose and glycogen are carbohydrates."}],"2015-Q11a":[{"q":"Humans are heterotrophic and omnivorous. Explain each term. (2 points)","right":"Can't make its own food; eats both plants and animals","wrong":["Makes its own food; eats both plants and animals","Can't make its own food; eats only plants","Makes food by photosynthesis; eats only meat"],"why":"Two points: heterotrophs can't make their own food, so they eat other organisms; omnivores eat both plants and animals."},{"q":"What is a balanced diet?","right":"Each food type in the right amount","wrong":["Equal amounts of each food type","Lots of protein and no fat at all","Only fruit, vegetables and fibre"],"why":"A balanced diet has each food type in the right amount for your needs, not equal amounts of everything."}],"2015-Q11b":[{"q":"Which two parts of the small intestine could you label (S)?","right":"Duodenum and ileum","wrong":["Colon and rectum","Caecum and appendix","Liver and pancreas"],"why":"The small intestine is the duodenum then the ileum; colon, caecum and rectum are large intestine."},{"q":"What is lipase?","right":"An enzyme that digests fats (lipids)","wrong":["An enzyme that digests starch","An enzyme that digests protein","A bile salt that emulsifies fats"],"why":"Lipase is the enzyme that breaks lipids into fatty acids and glycerol."},{"q":"Which organ secretes lipase into the gut?","right":"Pancreas","wrong":["Liver","Gall bladder","Colon"],"why":"The pancreas sends lipase into the duodenum; the liver makes bile, which isn't an enzyme."},{"q":"If lipase acts in the duodenum, what is the rough pH there?","right":"pH 7 to 9","wrong":["pH 1 to 3","pH 4 to 6","pH 10 to 12"],"why":"Pancreatic juice and bile make the duodenum slightly alkaline, so lipase works at about pH 8."}],"2015-Q11c":[{"q":"What is the dental formula of an adult human?","right":"I 2/2, C 1/1, PM 2/2, M 3/3","wrong":["I 2/2, C 1/1, PM 3/3, M 2/2","I 3/3, C 1/1, PM 4/4, M 3/3","I 2/2, C 2/2, PM 2/2, M 3/3"],"why":"Each half jaw has 2 incisors, 1 canine, 2 premolars and 3 molars: 32 teeth in all."},{"q":"How do human teeth differ from the mammal in the photo?","right":"Humans have fewer incisors","wrong":["Humans have more incisors","Humans have longer canines","Humans have no canines"],"why":"Humans have 2 incisors in each half jaw; the animal in the photo has more, and much longer canines."},{"q":"What food does the mammal in the photo mainly eat? Explain your answer. (2 points)","right":"Meat: it has long, pointed canines","wrong":["Plants: it has long, pointed canines","Meat: it has short, blunt canines","Plants: it has broad, flat molars"],"why":"Two points: it mainly eats meat, and its long, pointed canines show this, as they grip and tear flesh."},{"q":"Give two functions of the large intestine. (2 points)","right":"Absorbs water; egests waste (faeces)","wrong":["Absorbs glucose; egests waste (faeces)","Absorbs water; makes digestive enzymes","Absorbs amino acids; stores bile"],"why":"Two points: the large intestine absorbs water and egests faeces; absorbing vitamins made by gut bacteria also counts."},{"q":"Outline two beneficial functions of the bacteria in the digestive tract. (2 points)","right":"Make vitamins B and K; help digest food","wrong":["Make vitamins B and K; cause stomach ulcers","Make insulin; help digest food","Make stomach acid; kill all microbes in food"],"why":"Two points: helpful gut bacteria make vitamins (B and K) and help digest food; outcompeting harmful microbes also counts."}],"2016-Q12a":[{"q":"Distinguish between excretion and egestion by writing a sentence about each. (2 points)","right":"Excretion removes metabolic waste; egestion removes undigested food","wrong":["Excretion removes undigested food; egestion removes metabolic waste","Excretion removes metabolic waste; egestion is taking in food","Excretion releases energy from food; egestion removes undigested food"],"why":"Two points: excretion gets rid of waste made by metabolism (like urea and CO2); egestion gets rid of food never digested (faeces)."}],"2016-Q15a":[{"q":"Which vein has capillaries at both ends?","right":"Hepatic portal vein","wrong":["Hepatic vein","Renal vein","Pulmonary vein"],"why":"The portal vein starts in capillaries in the intestine and ends in capillaries in the liver."}],"2016-Q15c":[{"q":"Why is eating more wholegrain food good for you?","right":"Their fibre stimulates peristalsis","wrong":["Their fibre is digested to glucose","Their fibre slows peristalsis down","Their fibre is absorbed into blood"],"why":"Wholegrains are high in fibre, which adds bulk and stimulates peristalsis, moving food through the gut."}],"2017-Q14c":[{"q":"State two ways a villus is adapted for absorbing soluble food. (2 points)","right":"Wall one cell thick; large surface area (microvilli)","wrong":["Wall many cells thick; large surface area (microvilli)","Wall one cell thick; cilia that sweep food inside","Small surface area; very few blood capillaries"],"why":"Two points, e.g. a wall only one cell thick and a large surface area (microvilli); a rich blood supply or a lacteal also count."}],"2018-Q12b":[{"q":"What is the storage polysaccharide in humans?","right":"Glycogen","wrong":["Starch","Glucagon","Cellulose"],"why":"Animals store glucose as glycogen; starch is the plant store and glucagon is a hormone."},{"q":"Where is glycogen mainly stored?","right":"Liver","wrong":["Pancreas","Gall bladder","Small intestine"],"why":"Glycogen is stored mainly in the liver and muscles; the pancreas only makes the hormones that control it."}],"2018-Q15b":[{"q":"Why does bile contain bile salts and sodium hydrogencarbonate? (2 points)","right":"Emulsify fats; neutralise acid from the stomach","wrong":["Digest fats into fatty acids; neutralise stomach acid","Emulsify fats; make the duodenum more acidic","Emulsify proteins; neutralise acid from the stomach"],"why":"Two points: bile salts emulsify fats, and alkaline hydrogencarbonate neutralises stomach acid, giving enzymes a suitable pH."}],"2019-Q15b":[{"q":"What does digestion mean?","right":"Breaking food down into simpler parts","wrong":["Releasing energy from food","Taking food into the mouth","Getting rid of undigested food"],"why":"Digestion is the breakdown of food; releasing energy from it is respiration, which happens later in cells."},{"q":"Give two reasons why digestion is necessary. (2 points)","right":"To make food soluble; so it is easier to absorb","wrong":["To make food insoluble; so it is easier to store","To make molecules larger; so they are easier to absorb","To release energy from food; so it is easier to absorb"],"why":"Two points: digestion makes food small and soluble, so it is easier to absorb and easier to transport in the blood."},{"q":"Name and describe how food is passed along the gut. (2 points)","right":"Peristalsis: waves of muscle contraction","wrong":["Ciliary action: cilia sweep food along","Gravity: food falls down the gut","Emulsification: bile pushes food on"],"why":"Peristalsis is waves of contraction in the gut's muscle layers that squeeze food along, even upside down."},{"q":"Which enzyme digests protein?","right":"Pepsin","wrong":["Amylase","Lipase","Maltase"],"why":"Pepsin is a protease, so it digests protein; amylase and maltase digest carbohydrate, and lipase fat."},{"q":"Where is pepsin produced?","right":"Stomach","wrong":["Liver","Salivary glands","Gall bladder"],"why":"Pepsin is made by glands in the stomach wall, released as pepsinogen and switched on by acid."},{"q":"Where is pepsin active?","right":"Stomach","wrong":["Mouth","Large intestine","Liver"],"why":"Pepsin works in the stomach, where acid gives it the low pH (about 2) it needs."},{"q":"What does complete protein digestion produce?","right":"Amino acids","wrong":["Fatty acids","Glucose","Glycerol"],"why":"Proteins are chains of amino acids, so fully digesting them releases amino acids."},{"q":"Which vessel takes digested food to the liver?","right":"Hepatic portal vein","wrong":["Hepatic artery","Hepatic vein","Vena cava"],"why":"The hepatic portal vein runs from the intestine to the liver, carrying absorbed food."}],"2020-Q13b":[{"q":"Where in the body is urea made?","right":"Liver","wrong":["Kidney","Bladder","Pancreas"],"why":"The liver makes urea when it breaks down spare amino acids; the kidneys only filter it out."},{"q":"Which food biomolecule does urea come from?","right":"Protein","wrong":["Carbohydrate","Lipid","Fibre"],"why":"Urea comes from amino acids: when spare protein is broken down, its nitrogen part becomes urea."}],"2021-Q14a":[{"q":"What is digestion?","right":"Breakdown of food into soluble molecules","wrong":["Building large molecules from small ones","Releasing energy from glucose","Absorption of food into the blood"],"why":"Digestion breaks food down; absorption comes after it, and releasing energy is respiration."},{"q":"Why do humans need to digest food?","right":"Makes food soluble so blood can carry it","wrong":["Makes food insoluble so it is stored","Builds food into larger molecules","Kills germs found in food"],"why":"Small, soluble molecules can be absorbed and carried in the blood; large ones can't."},{"q":"What is the removal of undigested waste called?","right":"Egestion","wrong":["Excretion","Ingestion","Secretion"],"why":"Egestion removes undigested food as faeces; excretion removes waste made by metabolism, like urea."}],"2021-Q14b":[{"q":"Where are villi most plentiful?","right":"Small intestine","wrong":["Large intestine","Stomach","Oesophagus"],"why":"Villi line the small intestine, where most digested food is absorbed."},{"q":"What is the main job of villi?","right":"Increase the surface area for absorption","wrong":["Push food along the intestine","Store digested food for later","Churn food into chyme"],"why":"Villi are tiny folds that hugely increase the surface area, so digested food is absorbed quickly."},{"q":"On the diagram, what is X and what does it do?","right":"Lacteal: absorbs digested fats","wrong":["Capillary: carries oxygen to villus","Artery: brings blood from the heart","Microvillus: adds surface area"],"why":"X is the lacteal, a lymph vessel that takes in fatty acids and glycerol; capillaries take in sugars."},{"q":"Which vessel carries digested food away from the gut?","right":"Hepatic portal vein","wrong":["Hepatic artery","Hepatic vein","Inferior vena cava"],"why":"Blood from the gut's capillaries drains into the hepatic portal vein, which leads to the liver."},{"q":"Which organ do digested nutrients go to first?","right":"Liver","wrong":["Kidneys","Pancreas","Gall bladder"],"why":"The hepatic portal vein takes absorbed food straight to the liver, which processes it first."},{"q":"Which is a job of the liver, other than storing nutrients?","right":"Breaking down toxins such as alcohol","wrong":["Making insulin for blood sugar","Making lipase and amylase","Filtering urea into urine"],"why":"The liver detoxifies harmful substances; insulin and lipase come from the pancreas and urine from the kidneys."},{"q":"Name and explain how food is moved along the digestive system. (2 points)","right":"Peristalsis: muscular contractions of the gut wall push food along","wrong":["Peristalsis: cilia lining the gut beat to push food along","Egestion: muscular contractions of the gut wall push food along","Gravity: food falls through the gut under its own weight"],"why":"Two points: the process is peristalsis, and muscles in the gut wall contract in waves behind the food, squeezing it along."}],"2022-Q6":[{"q":"What can you conclude from the graph?","right":"Lipid is digested faster with bile salts added","wrong":["Lipid is digested faster with lipase alone","Bile salts digest lipid with no lipase","Bile salts double the total lipid digested"],"why":"The solid line (lipase and bile salts) rises more steeply, so digestion is faster; both end at the same level."},{"q":"What are the two products of lipid digestion?","right":"Fatty acids and glycerol","wrong":["Amino acids and peptides","Glucose and maltose","Cholesterol and bile salts"],"why":"Lipase splits each lipid into fatty acids and glycerol."},{"q":"Where in the gut does lipase digest lipids?","right":"Duodenum","wrong":["Pancreas","Liver","Gall bladder"],"why":"Lipase from the pancreas acts in the duodenum; the pancreas only makes it and the gall bladder stores bile."},{"q":"If lipase acts in the duodenum, what is its optimum pH?","right":"About pH 8","wrong":["About pH 2","About pH 5","About pH 12"],"why":"Bile and pancreatic juice make the duodenum slightly alkaline, about pH 7 to 9."},{"q":"What do bile salts do to lipids?","right":"Emulsify them into small droplets","wrong":["Digest them into fatty acids","Join them into larger droplets","Carry them into the lacteals"],"why":"Bile salts break lipid into tiny droplets, giving lipase more surface area, which is why digestion speeds up."},{"q":"Which structure in a villus absorbs lipid products?","right":"Lacteal","wrong":["Blood capillary","Microvillus","Hepatic portal vein"],"why":"Fatty acids and glycerol pass into the lacteal, the lymph vessel at the centre of the villus."}],"2023-Q17c":[{"q":"Which vein carries blood from the intestine to the liver?","right":"Hepatic portal vein","wrong":["Hepatic vein","Renal vein","Vena cava"],"why":"The hepatic portal vein links the intestine to the liver; the hepatic vein drains the liver."}],"2024-Q3":[{"q":"Name tube A, organ B and gland C on the diagram. (3 points)","right":"A: oesophagus; B: liver; C: pancreas","wrong":["A: trachea; B: liver; C: pancreas","A: oesophagus; B: pancreas; C: liver","A: oesophagus; B: liver; C: gall bladder"],"why":"Three points: tube A is the oesophagus, organ B is the liver, and gland C, behind and below the stomach, is the pancreas."},{"q":"What does tube A, the oesophagus, do?","right":"Carries food to the stomach","wrong":["Carries air to the lungs","Digests starch with amylase","Absorbs water from food"],"why":"The oesophagus moves swallowed food from the mouth to the stomach by peristalsis; the trachea carries air."},{"q":"What is one job of organ B, the liver?","right":"Stores glycogen","wrong":["Stores bile","Makes insulin","Makes lipase"],"why":"The liver stores glycogen (and makes bile); the gall bladder stores bile and the pancreas makes insulin and lipase."},{"q":"What does gland C do for digestion?","right":"Makes enzymes like lipase and amylase","wrong":["Makes bile to emulsify fat","Stores bile until it is needed","Makes acid to kill germs"],"why":"The pancreas makes pancreatic juice full of enzymes and sends it into the duodenum."},{"q":"Which feature helps the small intestine do its job?","right":"Lined with many villi","wrong":["Lined with cilia","Has a smooth inner lining","Has thick walls to stop leaks"],"why":"Villi give a huge surface area for absorption; the wall is thin, not thick, and it has no cilia."},{"q":"Give two functions of the symbiotic bacteria in the gut. (2 points)","right":"Make vitamins B and K; help digest food","wrong":["Make vitamins B and K; make bile to emulsify fats","Make insulin; absorb amino acids into the blood","Make stomach acid; help digest food"],"why":"Two points: gut bacteria make vitamins (B and K) and help digest food; crowding out harmful microbes also counts."}],"2024-Q17a":[{"q":"From the graph, what is the optimum pH of enzyme A?","right":"pH 2","wrong":["pH 1","pH 3","pH 7"],"why":"Optimum pH is where the curve peaks; curve A peaks at pH 2."},{"q":"From the graph, what is the optimum pH of enzyme B?","right":"pH 7","wrong":["pH 6","pH 8","pH 2"],"why":"Curve B is highest at pH 7, so that is its optimum."},{"q":"Which enzyme is likely from the stomach, and why? (2 points)","right":"A: the stomach is strongly acidic","wrong":["B: the stomach is close to neutral","B: the stomach is slightly alkaline","B: its optimum is nearer body pH"],"why":"Stomach acid keeps the pH near 2, matching enzyme A's peak; B works near neutral."},{"q":"Give the product(s) of amylase, lipase and protease, in that order. (3 points)","right":"Maltose; fatty acids and glycerol; amino acids","wrong":["Glucose; fatty acids and glycerol; amino acids","Maltose; amino acids; fatty acids and glycerol","Maltose; fatty acids and glycerol; glucose"],"why":"Three points: amylase makes maltose, lipase makes fatty acids and glycerol, and protease makes amino acids (or peptides)."}],"2025-Q6":[{"q":"On the diagram, what is tube A?","right":"Oesophagus","wrong":["Trachea","Larynx","Duodenum"],"why":"A runs from the mouth down to the stomach: the oesophagus. The trachea leads to the lungs."},{"q":"Name and briefly describe how food travels through tube A. (2 points)","right":"Peristalsis: muscular contractions of its wall push food down","wrong":["Peristalsis: cilia lining its wall beat to sweep food down","Gravity: food simply falls down into the stomach by its weight","Diffusion: food spreads down from high to low concentration"],"why":"Two points: name it peristalsis, and say muscles in the oesophagus wall contract in waves behind the food, pushing it down."},{"q":"How does the pH of food change from A to B?","right":"It drops (becomes acidic)","wrong":["It rises (becomes alkaline)","It stays about the same","It becomes neutral (pH 7)"],"why":"Food leaves the near-neutral oesophagus and meets hydrochloric acid in the stomach, so the pH drops to about 2."},{"q":"Which pancreatic enzyme digests lipids?","right":"Lipase","wrong":["Amylase","Trypsin","Bile salts"],"why":"Lipase digests lipids; amylase digests starch, trypsin digests protein, and bile salts aren't enzymes."},{"q":"In your villus drawing, what sits in the centre?","right":"A lacteal surrounded by capillaries","wrong":["A capillary surrounded by lacteals","A gland that releases enzymes","A layer of muscle for peristalsis"],"why":"A villus has a central lacteal (for fats) wrapped in a network of blood capillaries (for sugars and amino acids)."}],"2025-Q17a":[{"q":"Which vessel carries the blood richest in nutrients?","right":"Hepatic portal vein","wrong":["Hepatic vein","Hepatic artery","Aorta"],"why":"Blood leaving the gut in the portal vein is packed with absorbed food, before the liver takes some out."}],"2026-Q7c":[{"q":"Gall bladder: give its precise location and its main function. (2 points)","right":"Just under the liver; stores bile until it is needed","wrong":["Just under the liver; makes bile to emulsify fats","Behind the stomach; stores bile until it is needed","Just under the liver; makes lipase for the duodenum"],"why":"Two points: the gall bladder sits just underneath the liver, and it stores bile (made by the liver) until fatty food arrives."}],"2026-Q17a":[{"q":"Which is a real effect of diet on the circulatory system?","right":"Too much salt raises blood pressure","wrong":["Too much salt lowers blood pressure","Saturated fat keeps arteries clear","Fibre raises blood cholesterol"],"why":"Salt raises blood pressure, and saturated fat and cholesterol clog arteries, raising the risk of heart disease."}],"S1-Q1a":[{"q":"In the pictures, which organ is B?","right":"Pancreas","wrong":["Gall bladder","Spleen","Stomach"],"why":"B is the pancreas: a yellowish gland lying in the C-shaped curve of the duodenum."},{"q":"What role does organ A, the liver, play in digestion? (2 points)","right":"Makes bile, which emulsifies fats","wrong":["Makes lipase to digest fats","Stores bile until fatty food arrives","Makes acid to digest protein"],"why":"The liver makes bile, which breaks fat into small droplets; the gall bladder stores it and the pancreas makes lipase."}],"S1-Q6c":[{"q":"What is the normal pH of the stomach?","right":"About pH 2","wrong":["About pH 7","About pH 8","About pH 10"],"why":"Hydrochloric acid makes the stomach strongly acidic, around pH 2."},{"q":"What is one job of stomach acid?","right":"Kills bacteria swallowed with food","wrong":["Emulsifies fat into droplets","Turns starch into maltose","Activates salivary amylase"],"why":"Acid kills most microbes in food and gives pepsin its low pH; it actually stops salivary amylase."}],"S2-Q7c":[{"q":"In your diagram, which order does food pass through?","right":"Mouth, oesophagus, stomach, small intestine","wrong":["Mouth, trachea, stomach, small intestine","Mouth, oesophagus, small intestine, stomach","Mouth, stomach, oesophagus, small intestine"],"why":"Food goes mouth, oesophagus, stomach, small intestine, then large intestine; the trachea leads to the lungs."}]};
